function N({registerIndicator:y,nulls:f}){y({id:"oa-stochf",name:"Stochastic Fast (STOCHF)",category:"Oscillators",placement:"pane",inputs:[{key:"kLength",type:"number",label:"K Length",default:5,min:1,max:100,step:1,tooltip:"Period for calculating the raw %K line"},{key:"dLength",type:"number",label:"D Length",default:3,min:1,max:50,step:1,tooltip:"Smoothing period for the %D signal line"}],plots:[{key:"k",type:"line",title:"Fast %K",style:{color:"#ffeb3b",lineWidth:2}},{key:"d",type:"line",title:"Fast %D",style:{color:"#2962ff",lineWidth:2}}],calc(e,s){const p=Math.min(100,Math.max(1,Math.floor(Number(s.kLength)||5))),l=Math.min(50,Math.max(1,Math.floor(Number(s.dLength)||3))),o=new Array(e.length).fill(NaN),m=new Array(e.length).fill(NaN);let a=0;for(let t=0;t<e.length;t++){const k=Math.max(0,t-p+1);let i=1/0,h=-1/0;for(let n=k;n<=t;n++){const u=Number.isFinite(e[n].low)?e[n].low:0,d=Number.isFinite(e[n].high)?e[n].high:0;u<i&&(i=u),d>h&&(h=d)}const L=Number.isFinite(e[t].close)?e[t].close:0,r=h-i,c=r>0?100*(L-i)/r:0;o[t]=c,a+=c,t>=l&&(a-=o[t-l]);const g=Math.min(t+1,l);m[t]=g>0?a/g:c}return{k:f(o),d:f(m)}}})}export{N as default};
